282: /** rAF tick — 본인 라이더 마커 방향·페달 (동행과 동일 프레임) */
283: function syncLiveSelfRiderVisual(
284:   pos: LngLat,
285:   motion: LiveRiderMotion | null | undefined,
286:   routeGeometry: LineStringGeometry | null,
287:   prevLiveForBearingRef: { current: LngLat | null },
288:   flipRef: { current: HTMLDivElement | null },
289:   imgRef: { current: HTMLImageElement | null },
290:   spriteRef: { current: HTMLDivElement | null },
291:   prefersReducedMotion: boolean,
292: ): void {
293:   const prev = prevLiveForBearingRef.current;
294:   const b = resolveRiderBearingDeg(routeGeometry, pos, prev);
295:   prevLiveForBearingRef.current = pos;
296: 
297:   if (RIDER_PROTOTYPE_MODE === "iso2d") {
298:     const flip = flipRef.current;
299:     const img = imgRef.current;
300:     if (flip && img) applyIso2dRiderBearing(flip, img, "self", b);
301:     return;
302:   }
303:   if (RIDER_PROTOTYPE_IS_3D) return;
304: 
305:   const flip = flipRef.current;
306:   const sprite = spriteRef.current;
307:   if (!flip || !sprite) return;
308: 
309:   flip.style.transform = b > 90 && b < 270 ? "scaleX(-1)" : "scaleX(1)";
310: 
311:   const speedNow = motion?.speedKmh ?? 0;
312:   const pedalingRunning = motion != null && motion.sessionStatus === "running" && speedNow > 0.35;
313:   const rpm = motion
314:     ? resolvePedalCrankRpm({
315:         speedKmh: motion.speedKmh,
316:         crankRpmFromSensor: motion.crankRpmFromSensor,
317:       })
318:     : estimateCrankRpmFromSpeedKmh(0);
319:   let pedalLoopSec = 60 / rpm;
320:   pedalLoopSec = Math.min(5.5, Math.max(0.22, pedalLoopSec));
321:   sprite.style.animationDuration = `${pedalLoopSec}s`;
322:   const allowPedalAnim = !prefersReducedMotion && pedalingRunning;
323:   sprite.style.animationPlayState = allowPedalAnim ? "running" : "paused";
324: }
